class User {
  final String email;
  int logins = 0;

  User(this.email);

  String toString() => "User[$email]";

  String greet(String email) => 'Hi $email from ${this.email}';

  int login() {
    logins += 1;
    logins = logins + 10;
    return logins;
  }

  String shadow() {
    var email = 'local';
    return 'shadow: $email';
  }
}

class Point {
  int x;
  int y;
  int sum = 0;

  Point(this.x, this.y) {
    sum = x + y;
  }

  String toString() => '($x, $y) = $sum';
}

void main() {
  var u1 = User("foo@mail.com");
  print(u1);
  print(u1.greet('bar'));
  print(u1.login());
  print(u1.shadow());
  var p = Point(3, 4);
  print(p);
}
